import {renderPlanningSettings,esc} from './views.js';

export function renderSettingsView(state,{hasRestorePoint=false,hasMigrationPoint=false}={}) {
  const s=state.settings;
  return `<div class="page-heading compact"><div><h1>Settings</h1><p class="subtitle">Your study rhythm and your data.</p></div><span class="version-label">LearningOS 0.8.0</span></div>
  <section class="transfer-panel"><div><h2>Continue on another device</h2><p>Export here. Restore on the other computer. Keep one device up to date at a time.</p></div><div class="button-row"><button class="primary" data-action="export">Export backup</button><button class="secondary" data-action="import">Restore backup</button></div><small>Your progress saves in this browser. Exporting pauses a running timer; restoring previews the file and keeps a recovery copy.</small></section>
  <form id="settings-form" class="settings-stack">
    <section class="settings-section"><h2>Focus & breaks</h2><div class="form-columns"><label>Focus minutes<input name="focusMinutes" type="number" min="1" max="120" value="${s.focusMinutes}" required></label><label>Break minutes<input name="breakMinutes" type="number" min="1" max="30" value="${s.breakMinutes}" required></label></div><label>Study timezone<input name="timezone" value="${esc(s.timezone)}" list="study-timezones" required><datalist id="study-timezones"><option value="Africa/Casablanca"><option value="UTC"><option value="Europe/Paris"></datalist></label></section>
    <details class="settings-section"><summary>Exams & availability <span>Protect your time outside study.</span></summary><div class="settings-section-body"><label>Exam protection<select name="examMode">${[['auto','Follow calendar'],['on','Always protect for ENSAM'],['off','Off — keep independent study']].map(([v,label])=>`<option value="${v}" ${v===s.examMode?'selected':''}>${label}</option>`).join('')}</select></label><label class="checkbox"><input name="paused" type="checkbox" ${s.paused?'checked':''}> Pause independent roadmap</label><div class="form-columns"><label>Weekday minutes<input name="dailyMinutes" type="number" min="25" max="90" value="${s.dailyMinutes}" required></label><label>Saturday minutes<input name="saturdayMinutes" type="number" min="25" max="180" value="${s.saturdayMinutes}" required></label></div><label>Weekly self-study ceiling (hours)<input name="weeklyHours" type="number" min="0" max="8" step="0.25" value="${s.weeklyMinutes/60}" required></label>${renderPlanningSettings(state)}<p class="small muted">Edit academic windows in Calendar. Planning dates remain separate from your personal exam timetable.</p></div></details>
    <div class="settings-save"><button class="primary" type="submit">Save preferences</button></div>
  </form>
  <details class="settings-section"><summary>Backup recovery & reconciliation <span>Return to an earlier plan or combine compatible attempts.</span></summary><div class="settings-section-body"><p class="muted">Restore replaces the destination plan. Reconcile only appends compatible attempts for known tasks; it does not merge curriculum edits.</p><div class="button-row"><button class="secondary" data-action="reconcile">Reconcile attempts</button>${hasRestorePoint?'<button class="text-button" data-action="recover">Recover previous plan</button>':''}${hasMigrationPoint?'<button class="text-button" data-action="recover-migration">Recover pre-upgrade plan</button>':''}</div></div></details>
  <details class="settings-section"><summary>Local notes <span>Review an Obsidian note without changing completion.</span></summary><div class="settings-section-body"><p class="muted">Selected notes stay in your browser and exported backups. You confirm the next task yourself.</p><button class="secondary" data-action="note">Review an Obsidian note ↗</button></div></details>`;
}
